#include <stdio.h>

#define MAXN 1005

unsigned int card[MAXN];
int cnt[MAXN];

int main(void)
{
    int n, i, sum = 0, best = -1, arg = 0;

    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%u", &card[i]);
    }

    for (i = 0; i < n; i++) {
        unsigned int x = card[i];
        int c = 0;
        while (x > 0) {
            c += (int)(x & 1u);
            x >>= 1;
        }
        cnt[i] = c;
        sum += c;
        if (c > best) {
            best = c;
            arg = (int)card[i];
        }
    }

    for (i = 0; i < n; i++) {
        if (i > 0) {
            printf(" ");
        }
        printf("%d", cnt[i]);
    }
    printf("\n");
    printf("SUM %d\n", sum);
    printf("MAX %d\n", arg);
    return 0;
}

