#include <stdio.h>

#define MAXN 200005

int a[MAXN];

/* 第一个大于等于 x 的下标，范围 0..n */
int lowerBound(int arr[], int n, int x)
{
    int l = 0, r = n;
    while (l < r) {
        int mid = l + (r - l) / 2;
        if (arr[mid] < x) {
            l = mid + 1;
        } else {
            r = mid;
        }
    }
    return l;
}

/* 第一个大于 x 的下标，范围 0..n */
int upperBound(int arr[], int n, int x)
{
    int l = 0, r = n;
    while (l < r) {
        int mid = l + (r - l) / 2;
        if (arr[mid] <= x) {
            l = mid + 1;
        } else {
            r = mid;
        }
    }
    return l;
}

int main(void)
{
    int n, m, i, t, x;

    scanf("%d%d", &n, &m);
    for (i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    for (i = 0; i < m; i++) {
        scanf("%d%d", &t, &x);
        if (t == 1) {
            int cnt = upperBound(a, n, x) - lowerBound(a, n, x);
            printf("%d\n", cnt);
        } else if (t == 2) {
            int p = lowerBound(a, n, x);
            printf("%d\n", p < n ? p + 1 : 0);
        } else {
            int p = upperBound(a, n, x);
            printf("%d\n", p);
        }
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAXN 100005

typedef struct {
    int id;
    int math;
    int eng;
    int total;
} Player;

Player stu[MAXN];

/* 总分降序 -> 数学降序 -> 编号升序 */
int cmp(const void *pa, const void *pb)
{
    const Player *a = (const Player *)pa;
    const Player *b = (const Player *)pb;

    if (a->total != b->total) {
        return a->total > b->total ? -1 : 1;
    }
    if (a->math != b->math) {
        return a->math > b->math ? -1 : 1;
    }
    if (a->id != b->id) {
        return a->id < b->id ? -1 : 1;
    }
    return 0;
}

int main(void)
{
    int n, k, i;

    scanf("%d%d", &n, &k);
    for (i = 0; i < n; i++) {
        scanf("%d%d%d", &stu[i].id, &stu[i].math, &stu[i].eng);
        stu[i].total = stu[i].math + stu[i].eng;
    }

    qsort(stu, (size_t)n, sizeof(Player), cmp);

    for (i = 0; i < k; i++) {
        printf("%d %d\n", stu[i].id, stu[i].total);
    }
    return 0;
}

#include <stdio.h>

#define MAXN 100005

long long a[MAXN];

int main(void)
{
    int n, i;
    long long cur, best;
    int cs, bs, be;

    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%lld", &a[i]);
    }

    best = a[0];
    bs = 0;
    be = 0;
    cur = a[0];
    cs = 0;

    for (i = 1; i < n; i++) {
        if (cur + a[i] >= a[i]) { /* 相等时沿用更早的起点 */
            cur += a[i];
        } else {
            cur = a[i];
            cs = i;
        }
        if (cur > best || (cur == best && (cs < bs || (cs == bs && i < be)))) {
            best = cur;
            bs = cs;
            be = i;
        }
    }

    printf("%lld %d %d\n", best, bs + 1, be + 1);
    return 0;
}

#include <stdio.h>

#define MAXV 1000000

static char isPrime[MAXV + 2];
static int pre[MAXV + 2];

int main(void)
{
    int q, i, j, l, r;

    for (i = 2; i <= MAXV; i++) {
        isPrime[i] = 1;
    }
    for (i = 2; (long long)i * i <= MAXV; i++) {
        if (isPrime[i]) {
            for (j = i * i; j <= MAXV; j += i) {
                isPrime[j] = 0;
            }
        }
    }
    pre[0] = 0;
    for (i = 1; i <= MAXV; i++) {
        pre[i] = pre[i - 1] + (isPrime[i] ? 1 : 0);
    }

    scanf("%d", &q);
    for (i = 0; i < q; i++) {
        scanf("%d%d", &l, &r);
        printf("%d\n", pre[r] - pre[l - 1]);
    }
    return 0;
}

#include <stdio.h>

static const int mdays[13] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

static int isLeap(int y)
{
    return (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
}

/* 从 1900-01-01 起算，返回该日期是第几天（0 开始） */
static long long serial(int y, int m, int d)
{
    long long s = 0;
    int i;

    for (i = 1900; i < y; i++) {
        s += isLeap(i) ? 366 : 365;
    }
    for (i = 1; i < m; i++) {
        s += mdays[i];
        if (i == 2 && isLeap(y)) {
            s += 1;
        }
    }
    s += d - 1;
    return s;
}

int main(void)
{
    int y1, m1, d1, y2, m2, d2;
    long long diff;

    scanf("%d%d%d", &y1, &m1, &d1);
    scanf("%d%d%d", &y2, &m2, &d2);

    diff = serial(y1, m1, d1) - serial(y2, m2, d2);
    if (diff < 0) {
        diff = -diff;
    }
    printf("%lld\n", diff);
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAXL 1005

int main(void)
{
    char s1[MAXL], s2[MAXL];
    int res[MAXL + 2];
    int n1, n2, len, i, carry, top;

    scanf("%s", s1);
    scanf("%s", s2);
    n1 = (int)strlen(s1);
    n2 = (int)strlen(s2);
    len = (n1 > n2) ? n1 : n2;

    for (i = 0; i <= len + 1; i++) {
        res[i] = 0;
    }

    carry = 0;
    for (i = 0; i < len; i++) {
        int d1 = (i < n1) ? s1[n1 - 1 - i] - '0' : 0;
        int d2 = (i < n2) ? s2[n2 - 1 - i] - '0' : 0;
        int sum = d1 + d2 + carry;
        res[i] = sum % 10;
        carry = sum / 10;
    }
    if (carry > 0) {
        res[len] = carry;
    }

    top = len;
    while (top > 0 && res[top] == 0) {
        top--;
    }
    for (i = top; i >= 0; i--) {
        printf("%d", res[i]);
    }
    printf("\n");
    return 0;
}

#include <stdio.h>

#define MAXN 100005

int h[MAXN];

static void swapElem(int *x, int *y)
{
    int t = *x;
    *x = *y;
    *y = t;
}

/* 三数取中：调整后 h[l] <= h[mid] <= h[r]，再把中位数换到 h[l] 作基准 */
static void medianToLeft(int l, int r)
{
    int mid = l + (r - l) / 2;

    if (h[mid] < h[l]) {
        swapElem(&h[mid], &h[l]);
    }
    if (h[r] < h[l]) {
        swapElem(&h[r], &h[l]);
    }
    if (h[r] < h[mid]) {
        swapElem(&h[r], &h[mid]);
    }
    swapElem(&h[l], &h[mid]);
}

/* 挖坑法分区：返回基准的最终下标，左侧元素都不大于基准，右侧都不小于基准 */
static int partition(int l, int r)
{
    int pivot, i, j;

    medianToLeft(l, r);
    pivot = h[l];
    i = l;
    j = r;
    while (i < j) {
        while (i < j && h[j] > pivot) {
            j--;
        }
        if (i < j) {
            h[i] = h[j];
            i++;
        }
        while (i < j && h[i] < pivot) {
            i++;
        }
        if (i < j) {
            h[j] = h[i];
            j--;
        }
    }
    h[i] = pivot;
    return i;
}

static void quickSort(int l, int r)
{
    int cut;

    if (l >= r) {
        return;
    }
    cut = partition(l, r);
    quickSort(l, cut - 1);
    quickSort(cut + 1, r);
}

int main(void)
{
    int n, k, i;

    scanf("%d%d", &n, &k);
    for (i = 0; i < n; i++) {
        scanf("%d", &h[i]);
    }

    quickSort(0, n - 1);

    for (i = 0; i < n; i++) {
        if (i > 0) {
            printf(" ");
        }
        printf("%d", h[i]);
    }
    printf("\n");
    printf("KTH %d\n", h[k - 1]);
    return 0;
}

#include <stdio.h>

#define MAXN 100005

int h[MAXN];
int tmp[MAXN];
long long swaps = 0;

static void mergeSort(int l, int r)
{
    int mid, i, j, k;

    if (l >= r) {
        return;
    }
    mid = l + (r - l) / 2;
    mergeSort(l, mid);
    mergeSort(mid + 1, r);

    i = l;
    j = mid + 1;
    k = l;
    while (i <= mid && j <= r) {
        if (h[i] <= h[j]) {
            tmp[k++] = h[i++];
        } else {
            tmp[k++] = h[j++];
            swaps += (long long)(mid - i + 1);
        }
    }
    while (i <= mid) {
        tmp[k++] = h[i++];
    }
    while (j <= r) {
        tmp[k++] = h[j++];
    }
    for (k = l; k <= r; k++) {
        h[k] = tmp[k];
    }
}

int main(void)
{
    int n, i;

    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%d", &h[i]);
    }

    mergeSort(0, n - 1);

    printf("SWAPS %lld\n", swaps);
    for (i = 0; i < n; i++) {
        if (i > 0) {
            printf(" ");
        }
        printf("%d", h[i]);
    }
    printf("\n");
    return 0;
}

#include <stdio.h>

#define MAXN 1005
#define MOD 1000000007

static int dp[MAXN][MAXN];
static char blocked[MAXN][MAXN];

int main(void)
{
    int m, n, k, i, j, r, c;

    scanf("%d%d%d", &m, &n, &k);
    for (i = 0; i < k; i++) {
        scanf("%d%d", &r, &c);
        blocked[r][c] = 1;
    }

    if (blocked[1][1]) {
        printf("0\n");
        return 0;
    }
    dp[1][1] = 1;
    for (i = 1; i <= m; i++) {
        for (j = 1; j <= n; j++) {
            if (i == 1 && j == 1) {
                continue;
            }
            if (blocked[i][j]) {
                dp[i][j] = 0;
                continue;
            }
            {
                long long s = 0;
                if (i > 1) {
                    s += dp[i - 1][j];
                }
                if (j > 1) {
                    s += dp[i][j - 1];
                }
                dp[i][j] = (int)(s % MOD);
            }
        }
    }

    printf("%d\n", dp[m][n]);
    return 0;
}

#include <stdio.h>

typedef struct {
    long long m[2][2];
} Mat;

static long long MODV;

static Mat multiply(Mat a, Mat b)
{
    Mat c;
    int i, j, k;

    for (i = 0; i < 2; i++) {
        for (j = 0; j < 2; j++) {
            long long s = 0;
            for (k = 0; k < 2; k++) {
                s = (s + a.m[i][k] * b.m[k][j]) % MODV;
            }
            c.m[i][j] = s;
        }
    }
    return c;
}

int main(void)
{
    int q, i;
    long long n, e;

    scanf("%d", &q);
    for (i = 0; i < q; i++) {
        Mat base, res;

        scanf("%lld%lld", &n, &MODV);

        base.m[0][0] = 1; base.m[0][1] = 1;
        base.m[1][0] = 1; base.m[1][1] = 0;
        res.m[0][0] = 1;  res.m[0][1] = 0;
        res.m[1][0] = 0;  res.m[1][1] = 1;

        e = n - 1;
        while (e > 0) {
            if (e & 1) {
                res = multiply(res, base);
            }
            base = multiply(base, base);
            e >>= 1;
        }
        printf("%lld\n", res.m[0][0] % MODV);
    }
    return 0;
}
